import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  random,
  delayRender,
  continueRender,
} from '../remotionShim';
import { evolvePath } from "@remotion/paths";

// Custom font loading required by brand guidelines
if (typeof document !== "undefined") {
  const loadCustomFont = (family: string, url: string) => {
    const handle = delayRender(`Loading ${family}`);
    const format = url.endsWith(".otf")
      ? "opentype"
      : url.endsWith(".woff2")
      ? "woff2"
      : url.endsWith(".woff")
      ? "woff"
      : "truetype";
    const font = new FontFace(family, `url('${url}') format('${format}')`);
    font.load()
      .then(() => {
        document.fonts.add(font);
        continueRender(handle);
      })
      .catch((err) => {
        console.log(`Error loading ${family}`, err);
        continueRender(handle);
      });
  };
  loadCustomFont(
    "INTER-VARIABLEFONT_OPSZ,WGHT (3)",
    "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/brand_guidelines/fonts/732e34a8634944cb970162ec579b746a.TTF"
  );
}



export type BlueprintRevealProps = Record<string, any>;

const BlueprintReveal: React.FC<BlueprintRevealProps> = ({
  backgroundColor = "#07070a",
  transparentBackground = false,
  durationInSeconds = 10,
  frameworkColor = "#FFD700",
  glowIntensity = 15,
  dollarBillAmount = 40,
  dollarBillOpacity = 0.4,
  title = "FINANCIAL BLUEPRINT",
  titleFontFamily = "INTER-VARIABLEFONT_OPSZ,WGHT (3)",
  subtitle = "Building Modern Wealth",
  subtitleFontFamily = "INTER-VARIABLEFONT_OPSZ,WGHT (3)",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const fadeFrames = 3 * fps;

  // Global reveal interpolation
  const globalReveal = interpolate(frame, [0, fadeFrames], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Calculate blueprint SVG paths
  const paths = useMemo(() => {
    const pts: string[] = [];
    const cx = width / 2;
    // Shift slightly upward to accommodate text
    const cy = height / 2 - height * 0.05;
    const s = Math.min(width, height) * 0.35;

    // Isometric cube points
    const p0 = [cx, cy - s];
    const p1 = [cx + s * 0.866, cy - s * 0.5];
    const p2 = [cx + s * 0.866, cy + s * 0.5];
    const p3 = [cx, cy + s];
    const p4 = [cx - s * 0.866, cy + s * 0.5];
    const p5 = [cx - s * 0.866, cy - s * 0.5];
    const p6 = [cx, cy];

    // Main outer cube
    pts.push(`M ${p0[0]} ${p0[1]} L ${p1[0]} ${p1[1]} L ${p2[0]} ${p2[1]} L ${p3[0]} ${p3[1]} L ${p4[0]} ${p4[1]} L ${p5[0]} ${p5[1]} L ${p0[0]} ${p0[1]}`);
    pts.push(`M ${p6[0]} ${p6[1]} L ${p0[0]} ${p0[1]}`);
    pts.push(`M ${p6[0]} ${p6[1]} L ${p2[0]} ${p2[1]}`);
    pts.push(`M ${p6[0]} ${p6[1]} L ${p4[0]} ${p4[1]}`);

    // Inner secondary cube
    const innerS = s * 0.5;
    const i0 = [cx, cy - innerS];
    const i1 = [cx + innerS * 0.866, cy - innerS * 0.5];
    const i2 = [cx + innerS * 0.866, cy + innerS * 0.5];
    const i3 = [cx, cy + innerS];
    const i4 = [cx - innerS * 0.866, cy + innerS * 0.5];
    const i5 = [cx - innerS * 0.866, cy - innerS * 0.5];

    pts.push(`M ${i0[0]} ${i0[1]} L ${i1[0]} ${i1[1]} L ${i2[0]} ${i2[1]} L ${i3[0]} ${i3[1]} L ${i4[0]} ${i4[1]} L ${i5[0]} ${i5[1]} L ${i0[0]} ${i0[1]}`);
    
    // Connectors
    pts.push(`M ${p0[0]} ${p0[1]} L ${i0[0]} ${i0[1]}`);
    pts.push(`M ${p1[0]} ${p1[1]} L ${i1[0]} ${i1[1]}`);
    pts.push(`M ${p2[0]} ${p2[1]} L ${i2[0]} ${i2[1]}`);
    pts.push(`M ${p3[0]} ${p3[1]} L ${i3[0]} ${i3[1]}`);
    pts.push(`M ${p4[0]} ${p4[1]} L ${i4[0]} ${i4[1]}`);
    pts.push(`M ${p5[0]} ${p5[1]} L ${i5[0]} ${i5[1]}`);

    // Background geometric grid lines
    const numLines = 15;
    const stepX = width / numLines;
    const stepY = height / Math.round(numLines * (height / width));
    
    for (let i = 1; i < numLines; i++) {
      pts.push(`M ${i * stepX} 0 L ${i * stepX} ${height}`);
    }
    for (let i = 1; i < Math.floor(height / stepY); i++) {
      pts.push(`M 0 ${i * stepY} L ${width} ${i * stepY}`);
    }

    return pts;
  }, [width, height]);

  // Generate deterministic raining dollar bills
  const dollars = useMemo(() => {
    return Array.from({ length: dollarBillAmount }).map((_, i) => ({
      id: i,
      x: random(`dx-${i}`) * width,
      yOffset: random(`dy-${i}`) * height,
      scale: 0.5 + random(`ds-${i}`) * 1.5,
      speed: 1.5 + random(`dsp-${i}`) * 2.5,
      rotation: random(`dr-${i}`) * 360,
      rotSpeed: (random(`drs-${i}`) - 0.5) * 2,
      delay: random(`ddel-${i}`) * 30, // Frame delay for staggered fade-in
    }));
  }, [dollarBillAmount, width, height]);

  // Typography animations
  const textTranslateY = interpolate(frame, [30, fadeFrames], [40, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const textOpacity = interpolate(frame, [30, fadeFrames], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Cinematic radial gradient lighting behind elements */}
      {!transparentBackground && (
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            background: `radial-gradient(circle at 50% 45%, ${frameworkColor}33 0%, transparent 65%)`,
            opacity: globalReveal,
            transition: "none",
          }}
        />
      )}

      {/* Raining Dollar Bills */}
      <AbsoluteFill style={{ transition: "none" }}>
        {dollars.map((d) => {
          const y = (d.yOffset + frame * d.speed) % (height + 200) - 100;
          const rot = d.rotation + frame * d.rotSpeed;
          const billFade = interpolate(
            frame,
            [d.delay, d.delay + 60],
            [0, dollarBillOpacity],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <div
              key={d.id}
              style={{
                position: "absolute",
                left: d.x,
                top: y,
                transform: `scale(${d.scale}) rotate(${rot}deg)`,
                opacity: billFade * globalReveal,
                fontSize: "40px",
                pointerEvents: "none",
                userSelect: "none",
                transition: "none",
              }}
            >
              💵
            </div>
          );
        })}
      </AbsoluteFill>

      {/* Glowing Blueprint Framework */}
      <svg
        width="100%"
        height="100%"
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          transition: "none",
        }}
      >
        <defs>
          <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation={glowIntensity} result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>
        {paths.map((p, i) => {
          // Stagger the drawing of the paths slightly for a progressive reveal
          const stagger = (i % 10) * 3;
          const pathProgress = interpolate(
            frame,
            [stagger, stagger + fadeFrames - 10],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          const evolution = evolvePath(pathProgress, p);
          
          // The first 11 lines form the central 3D cube structure
          const isGrid = i >= 11;
          const opacity = isGrid ? 0.2 : 0.85;
          const strokeW = isGrid ? 1 : 3;

          return (
            <path
              key={i}
              d={p}
              stroke={frameworkColor}
              strokeWidth={strokeW}
              fill="none"
              strokeDasharray={evolution.strokeDasharray}
              strokeDashoffset={evolution.strokeDashoffset}
              strokeLinecap="round"
              strokeLinejoin="round"
              opacity={opacity}
              filter={isGrid ? undefined : "url(#glow)"}
              style={{ transition: "none" }}
            />
          );
        })}
      </svg>

      {/* Typography layer */}
      <div
        style={{
          position: "absolute",
          bottom: height * 0.12,
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          opacity: textOpacity,
          transform: `translateY(${textTranslateY}px)`,
          textAlign: "center",
          padding: "0 5%",
          transition: "none",
        }}
      >
        <h1
          style={{
            fontFamily: titleFontFamily,
            fontSize: "64px",
            fontWeight: 800,
            color: "#FFFFFF",
            margin: 0,
            textTransform: "uppercase",
            letterSpacing: "4px",
            textShadow: `0 0 20px ${frameworkColor}80`,
            transition: "none",
          }}
        >
          {title}
        </h1>
        <h2
          style={{
            fontFamily: subtitleFontFamily,
            fontSize: "32px",
            fontWeight: 400,
            color: frameworkColor,
            margin: "16px 0 0 0",
            letterSpacing: "2px",
            textTransform: "uppercase",
            transition: "none",
          }}
        >
          {subtitle}
        </h2>
      </div>
    </AbsoluteFill>
  );
};

export default BlueprintReveal;